using System;
using System.IO;
using System.Linq;
using System.Collections.Generic;
using UnityEngine;
using UnityEditor;
using UnityEditor.SceneManagement;
using HarborValeGreybox.Driving;
using HarborValeGreybox.Racing;
namespace HarborValeGreybox.Workshop.Editor {
public static class FitmentVerification {
 static List<string> lines=new List<string>();static void Check(bool good,string text){lines.Add((good?"PASS ":"FAIL ")+text);if(!good)throw new Exception(text);}static void Reject(Action action,string text){bool rejected=false;try{action();}catch{rejected=true;}Check(rejected,text);}
 public static void Run(){Directory.CreateDirectory("Verification/Fitment");try{
  var catalog=WorkshopCatalog.Load("car_finch");Check(catalog.offers.Length==55,"55 offers include six tire/drivetrain choices");var route=JsonUtility.FromJson<TrialDefinition>(Resources.Load<TextAsset>("FirstDocksideTrial").text);string fixture=Path.GetFullPath("Verification/Fitment/fixtures/released-v5.json"),bytes=File.ReadAllText(fixture);var old=JsonUtility.FromJson<RaceProgress>(bytes);string folder=Path.GetFullPath("Verification/Fitment/profiles/"+Guid.NewGuid().ToString("N"));Directory.CreateDirectory(folder);string file=folder+"/profile-v6.json";var store=new RaceProgressStore(file,route,recentLegacyFile:fixture);Check(store.Profile.version==6&&File.Exists(file),"Real released v5 ledger imports once into materialized v6");Check(File.ReadAllText(fixture)==bytes,"Old v5 file remains byte-identical");Check(store.Profile.profileId==old.profileId&&store.Profile.prototypeCarId==old.prototypeCarId&&store.Profile.availableCredits==old.availableCredits&&JsonUtility.ToJson(store.Profile.spending)==JsonUtility.ToJson(old.spending),"Migration preserves identity, balance and all historical receipts");Check(store.Profile.workshop.drive=="stock"&&store.Profile.workshop.tireCompound=="road"&&store.Profile.workshop.tireOwned==1,"Legacy migration defaults to original drivetrain and owned road set");
  int cash=store.Profile.availableCredits;string buy=Guid.NewGuid().ToString("N");store.PurchaseWorkshop(buy,"tire_drift",700,out bool duplicate);Check(!duplicate&&store.Profile.availableCredits==cash-700&&store.Profile.workshop.tireCompound=="drift"&&store.Profile.workshop.tireOwned==3,"First drift set purchase owns and fits for exact fee");store.PurchaseWorkshop(buy,"tire_drift",700,out duplicate);Check(duplicate&&store.Profile.availableCredits==cash-700,"Paid tire request retry is idempotent");store.PurchaseWorkshop(Guid.NewGuid().ToString("N"),"tire_road",0,out _);string fit=Guid.NewGuid().ToString("N");store.PurchaseWorkshop(fit,"tire_drift",0,out _);Check(store.Profile.availableCredits==cash-700&&store.Profile.workshop.tireCompound=="drift","Owned tire refit records no extra charge");store.PurchaseWorkshop(fit,"tire_drift",0,out duplicate);Check(duplicate,"Free tire refit request retry is idempotent");Reject(()=>store.PurchaseWorkshop(fit,"tire_slick",1200,out _),"Same transaction cannot be reused for another tire set");string snapshot=File.ReadAllText(file);Reject(()=>store.PurchaseWorkshop(Guid.NewGuid().ToString("N"),"tire_slick",0,out _),"Unowned slicks cannot be fitted for free");Check(File.ReadAllText(file)==snapshot,"Rejected quote leaves file byte-identical");store.PurchaseWorkshop(Guid.NewGuid().ToString("N"),"tire_slick",1200,out _);Check(store.Profile.workshop.tireOwned==7&&store.Profile.workshop.tireCompound=="slick","Slick set ownership is separate and persistent");
  string tune=JsonUtility.ToJson(store.Profile.workshop);int prior=store.Profile.availableCredits;string convert=Guid.NewGuid().ToString("N");store.PurchaseWorkshop(convert,"drive_rwd",3600,out _);Check(store.Profile.workshop.drive=="rwd"&&store.Profile.availableCredits==prior-3600,"RWD kit charges once and selects layout atomically");store.PurchaseWorkshop(convert,"drive_rwd",3600,out duplicate);Check(duplicate&&store.Profile.availableCredits==prior-3600,"Conversion transaction retry does not double-charge");Reject(()=>store.PurchaseWorkshop(Guid.NewGuid().ToString("N"),"drive_rwd",3600,out _),"Already-fitted conversion cannot charge again");var before=JsonUtility.FromJson<WorkshopBuild>(tune);Check(store.Profile.workshop.naStage==before.naStage&&store.Profile.workshop.induction==before.induction&&store.Profile.workshop.inductionStage==before.inductionStage&&store.Profile.workshop.gearboxStage==before.gearboxStage&&store.Profile.workshop.tireOwned==before.tireOwned,"Conversion retains compatible paid parts and owned tires");var d=catalog.Resolve(store.Profile.workshop);var comparison=catalog.Copy(store.Profile.workshop);comparison.drive="stock";var original=catalog.Resolve(comparison);Check(d.massKg==original.massKg+35&&Math.Abs(d.efficiency-.88f)<.0001f&&d.torque.SequenceEqual(original.torque),"RWD mass/losses change without fabricating crank torque");
  var loaded=new RaceProgressStore(file,route,recentLegacyFile:fixture);Check(loaded.Profile.workshop.drive=="rwd"&&loaded.Profile.workshop.tireOwned==7&&loaded.Profile.workshop.tireCompound=="slick","Conversion, tire inventory and fitment replay after reload");Check(File.ReadAllText(fixture)==bytes,"Later v6 transactions never modify or reimport v5 source");string frozen=File.ReadAllText(file);var fault=new RaceProgressStore(file,route,()=>{throw new IOException("Injected write failure");});Reject(()=>fault.PurchaseWorkshop(Guid.NewGuid().ToString("N"),"drive_awd",5200,out _),"Failed conversion commit reports failure");Check(File.ReadAllText(file)==frozen&&new RaceProgressStore(file,route).Profile.workshop.drive=="rwd","Failed write retains previous cash/build/receipt state");
  string unknown=folder+"/unknown.json";var future=JsonUtility.FromJson<RaceProgress>(frozen);future.version=7;File.WriteAllText(unknown,JsonUtility.ToJson(future));File.WriteAllText(unknown+".bak",frozen);Reject(()=>new RaceProgressStore(unknown,route),"Unknown v7 profile cannot be overwritten using older backup");Check(File.ReadAllText(unknown)==JsonUtility.ToJson(future),"Unknown newer file remains unchanged");
  string tampered=folder+"/tampered.json";var fake=JsonUtility.FromJson<RaceProgress>(frozen);fake.workshop.tireOwned=1;File.WriteAllText(tampered,JsonUtility.ToJson(fake));Reject(()=>new RaceProgressStore(tampered,route),"Cached inventory tampering cannot bypass receipt replay");
  int backCash=loaded.Profile.availableCredits;loaded.PurchaseWorkshop(Guid.NewGuid().ToString("N"),"drive_fwd",2600,out _);Check(loaded.Profile.availableCredits==backCash-2600&&loaded.Profile.workshop.drive=="fwd","Returning to stock layout is a new paid conversion job");
  var apex=WorkshopCatalog.Load("car_apex_test");var ab=new WorkshopBuild();var ad=apex.Resolve(ab);Check(ad.massKg==1250&&Math.Abs(ad.efficiency-.88f)<.0001f&&FitmentTuning.Drive(apex,ab)=="awd","Apex stock AWD preserves original mass and losses");ab.drive="rwd";var ar=apex.Resolve(ab);Check(ar.massKg==1225&&Math.Abs(ar.efficiency-.91f)<.0001f&&ar.torque.SequenceEqual(ad.torque),"Apex RWD changes mass and WHP losses without changing crank curve");
  string pref=folder+"/v6-audio.json",oldPref=folder+"/v5-audio.json";TurboAudioPreferenceStore.Save(oldPref,TurboReleaseMode.Flutter);string oldAudio=File.ReadAllText(oldPref);Check(TurboAudioPreferenceStore.LoadMigrated(pref,oldPref)==TurboReleaseMode.Flutter&&File.ReadAllText(oldPref)==oldAudio,"Turbo release preference migrates without modifying old settings");TurboAudioPreferenceStore.Save(oldPref,TurboReleaseMode.BlowOffValve);Check(TurboAudioPreferenceStore.LoadMigrated(pref,oldPref)==TurboReleaseMode.Flutter,"New audio preference is not repeatedly imported");PhysicsRules(catalog);File.WriteAllLines("Verification/Fitment/results.txt",lines);
 }catch(Exception e){lines.Add("FAIL "+e);File.WriteAllLines("Verification/Fitment/results.txt",lines);throw;}}
 static void PhysicsRules(WorkshopCatalog c){var previous=Physics.simulationMode;Physics.simulationMode=SimulationMode.Script;try{EditorSceneManager.OpenScene("Assets/HarborValeGreybox/Driving/Scenes/Finch_HandlingTest.unity");foreach(var spec in UnityEngine.Object.FindObjectsByType<StarterCarSpecification>(FindObjectsSortMode.None))UnityEngine.Object.DestroyImmediate(spec.gameObject);var prefab=AssetDatabase.LoadAssetAtPath<GameObject>("Assets/HarborValeGreybox/Expansion/Prefabs/AsterFinch.prefab");var g=(GameObject)PrefabUtility.InstantiatePrefab(prefab);g.transform.position=new Vector3(10,.35f,0);var car=g.AddComponent<FinchVehicle>();car.Initialize();car.externalInput=true;car.commandedHandbrake=false;
  foreach(var drive in new[]{"fwd","rwd","awd"}){var b=new WorkshopBuild{drive=drive};car.InstallPowertrain(c.Resolve(b));ChassisTuning.ApplyVehicle(c,b,car);FitmentTuning.ApplyVehicle(c,b,car);car.ResetAt(new Vector3(10,.35f,0),Quaternion.identity);for(int i=0;i<120;i++){car.Tick(.02f);Physics.Simulate(.02f);}car.commandedPedal=1;car.Tick(.02f);float front=Mathf.Abs(car.Wheels[0].motorTorque)+Mathf.Abs(car.Wheels[1].motorTorque),rear=Mathf.Abs(car.Wheels[2].motorTorque)+Mathf.Abs(car.Wheels[3].motorTorque);Check(drive=="fwd"?front>0&&rear==0:drive=="rwd"?front==0&&rear>0:front>0&&rear>0,"Actual motor torque is delivered to "+drive+" wheels");Check(car.driveLabel==drive.ToUpperInvariant()&&car.GroundedDrivenAxle(),drive+" label and grounded launch contacts reflect layout");car.commandedPedal=0;car.Recover();Check(car.driveLabel==drive.ToUpperInvariant(),drive+" persists through recovery");}
  foreach(string tires in new[]{"road","drift","slick"}){var b=new WorkshopBuild{tireCompound=tires,tireOwned=7};car.InstallPowertrain(c.Resolve(b));FitmentTuning.ApplyVehicle(c,b,car);if(tires=="road")Check(car.forwardGrip==1.15f&&car.lateralGrip==1.10f&&car.rearLateralGripMultiplier==1&&car.Wheels[2].sidewaysFriction.asymptoteValue==.78f,"Road tires retain original stock grip/curve");if(tires=="drift")Check(car.rearLateralGripMultiplier<1&&car.Wheels[2].sidewaysFriction.asymptoteValue>.78f&&car.Wheels[2].sidewaysFriction.extremumSlip>.22f,"Drift tires have progressive rear breakaway and broader slide grip");if(tires=="slick")Check(car.forwardGrip>1.15f&&car.lateralGrip>1.10f&&car.Wheels[2].sidewaysFriction.asymptoteValue<.78f,"Slicks increase dry peak grip and sharpen post-limit breakaway");}Check(car.Wheels.Length==4&&car.GetComponentsInChildren<WheelCollider>().Length==4,"Fitments retain one set of four wheel contacts");UnityEngine.Object.DestroyImmediate(g);
 }finally{Physics.simulationMode=previous;}}
 public static void Release(){Run();AvCameraVerification.Run();TurboAudioVerification.Run();AudioRules();HarborValeGreybox.Presentation.Editor.CityArtVerification.Release();}
 static void AudioRules(){var output=new List<string>();foreach(int rate in new[]{22050,44100,48000}){var quiet=new EngineSoundDsp(rate);var loaded=new EngineSoundDsp(rate);double delta=0;for(int i=0;i<rate;i++){float a=quiet.Sample(120,.15f,.1f,false,0),b=loaded.Sample(120,.15f,1,false,3);if(float.IsNaN(a)||float.IsNaN(b)||Math.Abs(a)>1||Math.Abs(b)>1)throw new Exception("Invalid engine waveform");delta+=Math.Abs(a-b);}if(delta/rate<.001)throw new Exception("Load/exhaust do not affect sound");output.Add("PASS Engine combustion responds to load/exhaust with finite signal at "+rate);}File.WriteAllLines("Verification/Fitment/audio.txt",output);}
}
}
